theme.css:
/* theme: Fractured Ledger | A day of institutional fractures and market tremors — the page splits between a cold blue institutional breakdown and a burning amber market slide, with a jagged red rule binding them. */
/* mood: bad */
/* layout: hero=centered; major-events=timeline/stack; political-news=outline/grid-2; financial-news=stat/stack; tech-news=banner/grid-2; entertainment-news=numbered/grid-2; sports=tile/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #2a1013;
  --ink: #f5e8e4;
  --ink-soft: #d6c4bf;
  --muted: #a88f8a;
  --accent: #ff5c5c;
  --accent-ink: #1a0d08;
  --rule: #4a2a2e;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

/* Hero: centered with a shattered rule */
.diary-page[data-hero="centered"] .diary-hero {
  background: linear-gradient(135deg, var(--paper-alt) 0%, var(--paper) 60%, var(--paper-alt) 100%);
  border-bottom: 3px solid var(--accent);
  position: relative;
}

.diary-page[data-hero="centered"] .diary-hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 48%, var(--rule) 48%, var(--rule) 52%, var(--accent) 52%, var(--accent) 100%);
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  position: relative;
}

.diary-page[data-hero="centered"] .diary-kicker {
  color: var(--accent);
  font-weight: 700;
  letter-spacing: 0.22em;
}

.diary-page[data-hero="centered"] .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 400;
  letter-spacing: -0.01em;
  line-height: 0.95;
  text-transform: uppercase;
  color: var(--ink);
  text-shadow: 0 2px 0 var(--accent);
}

.diary-page[data-hero="centered"] .diary-summary {
  border-left: 3px solid var(--accent);
  border-right: 3px solid var(--accent);
  padding: 0.5rem 1.25rem;
  font-style: italic;
  max-width: 44rem;
}

.diary-page[data-hero="centered"] .diary-theme-note {
  margin-top: 1.25rem;
}

.diary-page[data-hero="centered"] .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  clip-path: polygon(0 0, 100% 0, 92% 100%, 0 100%);
  padding: 0.15rem 0.9rem 0.15rem 0.6rem;
}

/* TOC: red rail */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* Sections: jagged red rule above each */
.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-section::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  width: 4rem;
  height: 3px;
  background: var(--accent);
  clip-path: polygon(0 0, 100% 0, 85% 100%, 0 100%);
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--ink);
}

/* Timeline cards: institutional fractures */
.diary-page [data-card="timeline"] .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-card="timeline"] .diary-card-inner::before {
  left: 0.4rem;
  width: 2px;
  background: linear-gradient(180deg, var(--accent) 0%, var(--rule) 100%);
}

.diary-page [data-card="timeline"] .diary-card-inner::after {
  left: 0;
  width: 0.9rem;
  height: 0.9rem;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper), 0 0 12px var(--accent);
}

.diary-page [data-card="timeline"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.5rem;
  color: var(--ink);
}

.diary-page [data-card="timeline"] .diary-card-body {
  color: var(--ink-soft);
}

/* Outline cards: political fault lines */
.diary-page [data-card="outline"] .diary-card-inner {
  padding: 1.5rem;
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
  position: relative;
}

.diary-page [data-card="outline"] .diary-card-inner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 30%, var(--rule) 30%, var(--rule) 100%);
}

.diary-page [data-card="outline"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--ink);
}

/* Stat cards: market slide */
.diary-page [data-card="stat"] .diary-card-inner {
  padding-top: 1rem;
  border-top: 3px solid var(--accent);
}

.diary-page [data-card="stat"] .diary-card-figure {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--accent);
  letter-spacing: -0.03em;
}

.diary-page [data-card="stat"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--ink);
}

/* Banner cards: tech turmoil */
.diary-page [data-card="banner"] .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
}

.diary-page [data-card="banner"] .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.diary-page [data-card="banner"] .diary-card-body {
  padding: 1.25rem;
  color: var(--ink-soft);
}

/* Numbered cards: entertainment */
.diary-page [data-card="numbered"] .diary-card-index {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--accent);
  font-size: 3.5rem;
}

.diary-page [data-card="numbered"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--ink);
}

/* Tile cards: sports */
.diary-page [data-card="tile"] .diary-card-inner {
  padding: 1.5rem;
  background: var(--paper-alt);
  border-left: 3px solid var(--accent);
}

.diary-page [data-card="tile"] .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  color: var(--ink);
}

/* Body text */
.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

/* Thread pills */
.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  background: transparent;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Markets */
.diary-page .diary-markets-label {
  color: var(--muted);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

/* Footer */
.diary-page .diary-footer {
  border-top-color: var(--rule);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Drop cap: red */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  color: var(--accent);
}

/* Subtle entrance for cards */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-card {
    animation: diary-rise 0.4s ease-out both;
  }

  .diary-page .diary-card:nth-child(2) {
    animation-delay: 0.05s;
  }

  .diary-page .diary-card:nth-child(3) {
    animation-delay: 0.1s;
  }

  .diary-page .diary-card:nth-child(4) {
    animation-delay: 0.15s;
  }

  .diary-page .diary-card:nth-child(5) {
    animation-delay: 0.2s;
  }
}

@keyframes diary-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
